\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 2. \plain \f1\lang1033\fs24 [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Merkverse zu den B\u252 \'fcchern des AT}}\plain \f1\lang1033\fs24 :] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quinque libri Moysi et alii cum eo}}\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Est Genes. Exod. Leui. Num. quoque Deutro / hinc Josue, Iudicum post Ruth quoque regum }}\plain \f1\i\lang1033\fs24 ...\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tobia Ester Iud, quas consequitur Iob}}\plain \f1\i\lang1033\fs24  ... - ... tot sunt libri in veteri testamento.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 \u196 \'c4hnliche Merkverse mit leicht abweichendem Incipit bei {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Walther, Initia, Nr. 5673}}\plain \f1\lang1033\fs20  (Est genes ex le num ...), {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 7141}}\plain \f1\lang1033\fs20  (Gen. Ex. Le. Nu. ...), {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 18824}}\plain \f1\lang1033\fs20  (Sunt Genes, ex, levi, nu ...) bzw. bei \plain \f1\scaps\lang1033\fs20 Stegm\plain \f1\scaps\lang1033\fs20 \u252 \'fc\plain \f1\scaps\lang1033\fs20 ller\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 RB IV, Nr. 8616}}\plain \f1\lang1033\fs20  (Sunt Genes. Ex. Le. Nu. De. Josu. Ju. Ruth. ...), jeweils mit Angaben zur \u220 \'dcberlieferung. In der Parallel\u252 \'fcberlieferung teilweise mit \u220 \'dcberschriften wie "Versus valentes ad sciendum numerum et ordinem librorum Bibliae, et quot capitula quilibet liber habeat" ({\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Basel, UB, B XI }}\plain \f1\lang1033\fs20 6, 134\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ) versehen. 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Rest der Seite leer.}

