\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 424rb-425va}}\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Judeneid}}\plain \f1\lang1033\fs22 :) \plain \f1\i\lang1033\fs22 >Sequitur. Dis ist der judenn eydt etc.<{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [I]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 r sullit wissen, das dye juden iren eydt sullen thun}}\plain \f1\i\lang1033\fs22  nach irer sachin vt xxi q. i. Mouet. Vnnd yn der wey\u223 \'dfe so sal ir eidt als ein cristenn eid sein: Al\u223 \'dfo das mir Gregor schulth gibet, das ich en geslagen hab, das byn ich vnschuldig ...\~\endash \~... Nota: Ir sulleth wissenn, das man eyn iglich membrum dis ob geschriben eydes nympt vor eynen ganczen eydt mit der beschuldigunge, do mitte man den juden beschuldigit.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Edition: \plain \f1\scaps\lang1033\fs20 Daniels\plain \f1\lang1033\fs20  / \plain \f1\scaps\lang1033\fs20 von Gruben\plain \f1\lang1033\fs20  (s.\~o.), Sp. 438 und Sp. 173-175.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

