\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (62\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 71}}\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistola I ad Thessalonicenses}}\plain \f1\lang1033\fs24 , \plain \f1\b\lang1033\fs24 Text\plain \f1\lang1033\fs24 ,
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (62\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -71\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Kommentar zu I Th\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 P<AVLVS et Siluanus et cetera}}\plain \f1\lang1033\fs24  (I Th 1,1). \plain \f1\i\lang1033\fs24 Hanc epistolam scribit apostolus Thessalonicensibus. Thessalonica est metropolis Macedonie, que est prouincia Grecorum. ... - ... uel sanctis, id est perfectis, ut inde proficiant, et ut in bonis operibus proficiatis. Gratia domini nostri Ihesu Christi sit uobis[cum]. Amen. \plain \f1\lang1033\fs24 (I Th 5,28).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Kommentar: PL 192, Sp. 289A-312A, vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 RB IV, Nr. 6662}}\plain \f1\lang1033\fs20 ,
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 selten interlineare Glossen, z. B. 70\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  zu I Th 5,19: nolite extinguere spiritum - \plain \f1\i\lang1033\fs20 vel: gratiam nolite celeare\plain \f1\lang1033\fs20 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

