\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (71\plain \f1\super\lang1033\fs24 vb{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 -77}}\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistola II ad Thessalonicenses}}\plain \f1\lang1033\fs24 , \plain \f1\b\lang1033\fs24 Text\plain \f1\lang1033\fs24 ,
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (71\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -77\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Kommentar zu II Th\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 P<AVLVS et Siluanus}}\plain \f1\i\lang1033\fs24  et cetera\plain \f1\lang1033\fs24  (II Th 1,1). \plain \f1\i\lang1033\fs24 Hanc epistolam scribit item apostolus Thessalonicensibus. Orta enim apud eos \plain \f1\lang1033\fs24 [PL: Graecos]\plain \f1\i\lang1033\fs24  grauiori tribulatione. Item monet eos ad patientiam ... - ... in fine omnium epistolarum salutationem se subscribere testatur, ut sub nomine eius nulla epistola \plain \f1\lang1033\fs24 [sonst:\plain \f1\i\lang1033\fs24  epistola nulla\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24  accipiatur, que non fuerit manu eius subscripta.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Kommentar: PL 192, Sp. 312B-326B, vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 RB IV, Nr. 6663}}\plain \f1\lang1033\fs20 ,
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 selten interlineare Glossen, z. B. 70\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  zu II Th 1,6: si tamen iustum - \plain \f1\i\lang1033\fs20 Ambrosius vel: si quidem\plain \f1\lang1033\fs20 .}

