\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >Incipit liber de virtutibus Capitulum primum de frugalitate\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >P<Aupertas est parui possessio}}\plain \f1\i\lang1033\fs24 . Honesta res est leta paupertas \plain \f1\lang1033\fs24 \u8230 \'85 - \u8230 \'85 \plain \f1\i\lang1033\fs24 non vertes terga sed sensum recedes intuitum. Explicit liber de virtutibus.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Eingeteilt in verschiedene Abschnitte: (228rb)\plain \f1\i\lang1033\fs20  >Contra cupiditatem<, \plain \f1\lang1033\fs20 (229ra)\plain \f1\i\lang1033\fs20  >Contra gulam et curam introducitur<, \plain \f1\lang1033\fs20 (230rb)\plain \f1\i\lang1033\fs20  >Contra appetitum humane glorie<, \plain \f1\lang1033\fs20 (230vb)\plain \f1\i\lang1033\fs20  >De adulacione<, \plain \f1\lang1033\fs20 (230vb)\plain \f1\i\lang1033\fs20  >De contemtu mundi<, \plain \f1\lang1033\fs20 (231va)\plain \f1\i\lang1033\fs20  >Contra ypocritas<, \plain \f1\lang1033\fs20 (231vb)\plain \f1\i\lang1033\fs20  >Contra instabiles<, \plain \f1\lang1033\fs20 (232va)\plain \f1\i\lang1033\fs20  >Contra solitarios< \plain \f1\lang1033\fs20 etc.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Systematische Sammlung von Seneca-Zitaten aus den Epistolae morales. Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M\u252 \'fcnchen, BSB, Clm 3941}}\plain \f2\lang1033\fs22  \plain \f1\lang1033\fs20 (S\u252 \'fcddeutschland: Augsburg, Stra\u223 \'dfburg; 15. Jh., 2. H\u228 \'e4lfte), 177r-197v; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Padua, Biblioteca Antoniana, 9 Scaff. I}}\plain \f1\lang1033\fs20 , 303v; {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Leipzig, UB, Ms 1263}}\plain \f1\lang1033\fs20 , 217r; {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Zwickau, Ratsschulbibliothek, Ms. XXXIII, I, 12}}\plain \f1\lang1033\fs20  (Deutschland, 1479), 230rb. Vgl. Beschreibung zu Clm 3941 von Juliane \plain \f1\scaps\lang1033\fs20 Trede\plain \f1\lang1033\fs20 : \plain \f1\lang1033\fs20\cf1 http://www.manuscripta-mediaevalia.de/dokumente/html/obj31782707\plain \f1\ul\lang1033\fs20\cf2 .}

