\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Hieronymus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Prologus}}\plain \f1\b\lang1033\fs24  zum Liber Ecclesiastes\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Memini ante me hoc ferme quinquennio, cum adhuc Rome essem, et Ecclesiastem sancte Blesille legerem}}\plain \f1\i\lang1033\fs24  ... - ... nec rursum contra conscientiam meam fonte veritatis omissio \plain \f1\lang1033\fs24 [sonst:\plain \f1\i\lang1033\fs24  omisso\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24  opinionum rivulos consectarer.\plain \f1\lang1033\fs20   \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 RB III, Nr. 3351}}\plain \f1\lang1033\fs24 ),
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Prolog vgl. PL 23, Sp. 1009C-1012A (Epistola ad Paulam et Eustochium, Praefatio);
