\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [S]}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ed quia essenciali dimisso nichil actum videtur}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 1. Artikel: [A]\plain \f1\i\lang1033\fs24 lienacio est contractus per quem dominium transfertur ...\plain \f1\lang1033\fs24 , es folgen nur die ersten Artikel: \plain \f1\i\lang1033\fs24 Arbiter\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 appelacio\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 accusacio\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 apostata\plain \f1\lang1033\fs24  etc. bis \plain \f1\i\lang1033\fs24 Atleta dicitur qui causa ...\plain \f1\lang1033\fs24 , bricht ab. Rest der Seite und 41\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24  (mit Seiteneinrichtung) leer.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Zum Inhalt und zur \u220 \'dcberlieferung (drei Textzeugen des 15. Jh.s:{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17  Basel, UB, C II 22}}\plain \f1\lang1033\fs20 , ohne Foliierung, Nr. 3, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M\u252 \'fcnchen, BSB, Clm 423, 1}}{\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 -38}}{\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 ;}}\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 W\u252 \'fcrzburg, UB, M. ch. f. 54, 33}}{\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 -55}}{\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 )}}\plain \f1\lang1033\fs20  vgl. \plain \f1\scaps\lang1033\fs20 Seckel\plain \f1\lang1033\fs20 , Geschichte beider Rechte, Bd. I, S. 367-374. In der W\u252 \'fcrzburger Hs. M. ch. f. 54 (S\u252 \'fcddeutschland, 1455) dieser Text als Teil 3 eines umfangreicheren Compendium utriusque iuris (Adiutorium pauperum) vgl. \plain \f1\scaps\lang1033\fs20 Thurn\plain \f1\lang1033\fs20 , UB W\u252 \'fcrzburg III/2, S. 28, sowie aktuelle Beschreibung mit Digitalisat: http://vb.uni-wuerzburg.de/ub/mchf54/inhalt.html. Au\u223 \'dferdem in {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M\u252 \'fcnchen, UB, 4\u176 \'b0 Cod. ms. 803}}\plain \f1\lang1033\fs20  (S\u252 \'fcddeutschland, 1458), 199\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -226\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  (hier als Vocabularius. Expositio praegnatiorum et magis difficilium terminorum iuris civilis et canonici), vgl. \plain \f1\scaps\lang1033\fs20 Reuter\plain \f1\lang1033\fs20 , M\u252 \'fcnchen, UB V, S. 242, sowie in {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Eichst\u228 \'e4tt, UB, Cod. st 498 (Eichst\u228 \'e4tt, Faszikel III: 1466), 197}}{\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 -214}}{\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 , }}\plain \f1\lang1033\fs20 vgl. \plain \f1\scaps\lang1033\fs20 Hilg\plain \f1\scaps\lang1033\fs20 /Keller\plain \f1\lang1033\fs20 , Eichst\u228 \'e4tt III, S. 112.}

