\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 1r-37v}}\plain \f1\lang1033\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Matth\u228 \'e4us-Evangelium}}
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 (Seitentitel \plain \f1\i\lang1033\fs22 >Matheus.<\plain \f1\lang1033\fs22 )\plain \f1\i\lang1033\fs22  >D<{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 as puch des geslechtz Ihesu Cristi, des suns Dauids, des suns Abraham, wan Abraham gebar Ysaac, wan Ysaac gebar Jacob}}\plain \f1\i\lang1033\fs22  ...\~\endash \~... Dor um get aus vnd lert alle leut vnd tauft si in dem namen dez vaterz vnd des sunes vnd des heiligen geistz vnd lert si ze behuten alle dink, di ich euch hab geboten, vnd secht, ich bin mit euch alle di tag vncz czu der vollentdunge der werlt. Amen.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Ed.: \plain \f1\scaps\lang1033\fs20 Kurrelmeyer\plain \f1\lang1033\fs20 , Bd. 1, S. 7-116; \plain \f1\scaps\lang1033\fs20 Klimesch\plain \f1\lang1033\fs20 , Bd. 1, S. 1-44.}

