\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Sequitur institucio papalis super festo Visitationis virginis gloriose Marie. \plain \f1\lang1033\fs24 [B]{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Onifacius episcopus seruus seruorum dei ad perpetuam rei memoriam. Superni benignitatis }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [sonst -tas]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  conditoris humanam creaturam }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [ad similitudinem suam creatam]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  misericordi pietate respiciens}}\plain \f1\i\lang1033\fs24  ... - ... et hic a noxiis protegi et in futuro sempiterna gaudia mereantur \plain \f1\lang1033\fs24 [vom Schreiber erg\u228 \'e4nzt:\plain \f1\i\lang1033\fs24  consequi\plain \f1\lang1033\fs24 ].
