\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 [A]{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ssumptus est in celum ... }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 (Mc 16,19)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Differentia est inter ascenscionem, assumpcionem et euolacionem. Ascensio fit propria}}\plain \f1\i\lang1033\fs24  virtute et appropriatur Christo ... - ... sedere habitare intelligitur \plain \f1\lang1033\fs24 [interlinear eingef\u252 \'fcgt: \plain \f1\i\lang1033\fs24 uel\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 intelligite quoniam dicius \plain \f1\lang1033\fs24 (?)\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [bricht ab, vgl. die Parallelstelle 250\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , Z. 6f.: \plain \f1\i\lang1033\fs24 quoniam dicit de quocumque ...\plain \f1\lang1033\fs24 ]. 253\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
