\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs20\chcbpat17 Fragm. 1}}\plain \f1\lang1033\fs20 : als {\field{\*\fldinst HYPERLINK "hida://5234/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 vorderer Spiegel}}\plain \f1\lang1033\fs20  querst\u228 \'e4ndig beschriebenes {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Blatt}}\plain \f1\lang1033\fs20  (Gr\u246 \'f6\u223 \'dfe {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 28 x 19}}\plain \f1\lang1033\fs20 ) verwendet, im oberen Teil ohne feste Schriftraumeinrichtung beschriftet, 12 Zeilen, {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Bastarda}}\plain \f1\lang1033\fs20 , geschrieben von einer Hand, die Hand 1 ({\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 um 1475-77}}\plain \f1\lang1033\fs20 , s. u. Fasz. II) sehr \u228 \'e4hnelt, nicht rubriziert. }

