\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5209/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Druck: Vincentius Bellovacensis: Speculum naturale}}\plain \f1\b\lang1033\fs22 .{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17  }}\plain \f1\b\lang1033\fs22 [{\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Strassburg}}\plain \f1\b\lang1033\fs22 : Drucker mit dem bizarren R ({\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Adolf Rusch}}\plain \f1\b\lang1033\fs22 ), nicht {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 nach 1476}}\plain \f1\b\lang1033\fs22 ] ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 GW M50635}}\plain \f1\b\lang1033\fs22 ), Band 1}

