\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Bl. 1-338}}\plain \f1\lang1033\fs20 . Rubriziert: rote Paragraphenzeichen. Am Beginn der B\u252 \'fccher (2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 3\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 7\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 49\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , 118\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 149\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 247\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 305\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ) rot-blau gespaltene bzw. einfarbige Initialen mit rot-blauer {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Fleuronn\u233 \'e9f\u252 \'fcllung}}\plain \f1\lang1033\fs20  sowie Besatz- und Ablaufmotiven. An Kapitelbeginn rote und blaue Lombarden. Blattweiser aus braunem Leder bei Buchbeginn: an Bl. 49, 117, 148, 247, 305 und 338, weitere Blattweiser verloren, z. B. Bl. 239.}

