\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De psalterio}}\plain \f1\b\lang1033\fs24  (Exzerpt aus {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Honorius Augustodunensis}}\plain \f1\b\lang1033\fs24 )\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >De psalterio<: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Psalterium non exteriori sed interiori homini loquitur, et non carni, sed spiritui}}\plain \f1\i\lang1033\fs24 . Et idcirco totum spiritualiter intelligitur. ... Cum in choro psallitur, tunc sunt uerba ecclesie deum laudantis ... - ... Benedicti vos domino etc.
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f2\lang1033\fs22 Exzerpt aus {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Honorius Augustodunensis}}\plain \f2\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 Selectorum psalmorum expositio}}\plain \f2\lang1033\fs22 , vgl. Druck PL 172, Sp. 274A-B. Ein Text mit diesem Incipit auch in Berlin, SBB-PK, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 Ms. theol. lat. fol. 682}}\plain \f2\lang1033\fs22  (Prag bzw. Mitteldtld., Nachtrag 15. Jh.), 1\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs22 , vgl. \plain \f2\scaps\lang1033\fs22\cf1 Becker\plain \f2\lang1033\fs22\cf1 /\plain \f2\scaps\lang1033\fs22\cf1 Brandis,\plain \f2\lang1033\fs22\cf1  Berlin I,2,2\plain \f2\lang1033\fs22 , S. 204.}

