\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra-rb\plain \f1\b\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gregorius Magnus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Moralia in Iob}}\plain \f1\b\lang1033\fs24 , lib. 23, pars 1 (Fragment)
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) [... ut de se humilia sentiant, et post se] \plain \f1\i\lang1033\fs24 iam corda innocen\plain \f1\lang1033\fs24 [tium non seducant?] \plain \f1\i\lang1033\fs24 Ceruice enim tumen\plain \f1\lang1033\fs24 [ti ab ecclesiae uniuers]\plain \f1\i\lang1033\fs24 itate resilierant,\plain \f1\lang1033\fs24  [et infirmos post se pop]\plain \f1\i\lang1033\fs24 ulos quasi sequen\plain \f1\lang1033\fs24 [tes greges trahebant.] \plain \f1\i\lang1033\fs24 Ueniant igitur\plain \f1\lang1033\fs24  [ad beatum Iob, id est re]\plain \f1\i\lang1033\fs24 ue\plain \f2\i\lang1024\fs24 rtantur ad \u281 \'eaccle\plain \f1\lang1033\fs24 [siam, et septenario sacri]\plain \f1\i\lang1033\fs24 ficio tauros et arietes\plain \f1\lang1033\fs24  [mactandos offerant] ... \plain \f1\i\lang1033\fs24 Cuius dum senten\plain \f1\lang1033\fs24 [tias minime re]\plain \f1\i\lang1033\fs24 spuit, sed tamen eum\plain \f1\lang1033\fs24  (1\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 ipsum qui illas protulit reprehen\plain \f1\lang1033\fs24 [dit, qua]\plain \f1\i\lang1033\fs24 si aperte insinuat, dicens: noui q\plain \f1\lang1033\fs24 [uae dicit]\plain \f1\i\lang1033\fs24 , sed ignoro quis \plain \f1\lang1033\fs24 [sonst: qui]\plain \f1\i\lang1033\fs24  dicit, ... \plain \f1\lang1033\fs24 [Hoc seruat] \plain \f1\i\lang1033\fs24 uoto, illud exercet minis\plain \f1\lang1033\fs24 [terio. Hanc au]\plain \f1\i\lang1033\fs24 tem dicendi formulam arrog\plain \f1\lang1033\fs24 [antes ignorant. ..., bricht ab].
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Ed.: CCSL 143B, S. 1148, Z. 186 - S. 1149, Z. 250.}

