\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Epitaphium Alberti Magni: Fenix doctorum, paris expers, philosophorum}}\plain \f1\i\lang1033\fs24  / princeps, verborum vas fundens dogma sacrorum ... - ... Annis bis denis minus octo actis mille trecenis / Christi nascentis.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Druck: {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Rodolphus de Novimagio}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Legenda litteralis Alberti Magni}}\plain \f1\lang1033\fs24 . Daran: {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Jacobus Magdalius Gaudensis}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Legenda compendiosa et metrica}}\plain \f1\lang1033\fs24 . K\u246 \'f6ln: {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johann Koelhoff}}\plain \f1\lang1033\fs24 , 11.IX.1490.\~GW M38537. Vgl. Digitalisat des Exemplars BSB-Ink R-284: http://daten.digitale-sammlungen.de/bsb00024041/image_80, hier am Ende mit zwei zus\u228 \'e4tzlichen Zeilen (... Christi nascentis de corpore exit habenis. Quinta post festum Martini luce molestum). Nach der \u220 \'dcberschrift im Druck handelt es sich um die originale Grabinschrift des Albertus Magnus. Zu ausgew\u228 \'e4hlten \u220 \'dcberlieferungszeugen (ohne diese Hs.) vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Walther, Initia, Nr. 14095}}\plain \f1\lang1033\fs24 . Eine weitere Abschrift auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mei\u223 \'dfen, Stadtarchiv, H 3}}\plain \f1\lang1033\fs24  (Sammelhs. des Johannes Fabri de Werdea, Fasz. VII: um 1475), 269\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 .}

