\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (li. Spalte) \plain \f1\b\i\lang1033\fs24 Epinicha\plain \f1\i\lang1033\fs24  neutrum\plain \f1\b\i\lang1033\fs24  \plain \f1\i\lang1033\fs24 ... sunt festiuitates et graciarum acciones pro victoria habite, ab epi: supra et nicos: victoria \plain \f1\lang1033\fs24 [Ex quo\plain \f1\lang1033\fs20  \plain \f1\lang1033\fs24 E 192.1: Epinichia; Brev. Druck S. 180], \plain \f1\b\i\lang1033\fs24 Euphonia uel Ephonia \plain \f1\i\lang1033\fs24 est dulcis et bonus sonus ... \plain \f1\lang1033\fs24 [Ex quo E 323; Brev. Druck S. 187], \plain \f1\b\i\lang1033\fs24 Epulum\plain \f1\i\lang1033\fs24  -li\plain \f1\b\i\lang1033\fs24  \plain \f1\i\lang1033\fs24 ... est ferculum non bene conditum ...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 proprie \plain \f1\b\i\lang1033\fs24 matten\plain \f1\lang1033\fs24  [Ex quo\plain \f1\lang1033\fs20  \plain \f1\lang1033\fs24 E 200; Brev. Druck S. 181], \plain \f1\b\i\lang1033\fs24 Epularius\plain \f1\i\lang1033\fs24 : m.: epulo scilicet epularum amator ... prausor: \plain \f1\b\i\lang1033\fs24 eyn esser\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 ...\plain \f1\lang1033\fs24  [Ex quo\plain \f1\lang1033\fs20  \plain \f1\lang1033\fs24 E 199.1; Brev: Hs., 87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ],\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [\plain \f1\b\lang1033\fs24 E\plain \f1\lang1033\fs24 ]\plain \f1\b\i\lang1033\fs24 quianimus\plain \f1\i\lang1033\fs24  ... paciens constans unius animi ... \plain \f1\lang1033\fs24 [Ex quo\plain \f1\lang1033\fs20  \plain \f1\lang1033\fs24 E 205.1: nur Lemma; Brev. Druck S. 181]\plain \f1\i\lang1033\fs24  ... - ... \plain \f1\b\i\lang1033\fs24 Equigium\plain \f1\i\lang1033\fs24  proprie \plain \f1\b\i\lang1033\fs24 eyn wettelofft\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24 , \plain \f1\b\i\lang1033\fs24 Equinoxium uel equidium\plain \f1\i\lang1033\fs24  dicitur equalitas noxium cum diebus et bis fit in anno ut circa festum Gregorii \plain \f1\lang1033\fs24 (12.03.) \plain \f1\i\lang1033\fs24 et Lamperti \plain \f1\lang1033\fs24 (17.09.), \plain \f1\i\lang1033\fs24 ...\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  \plain \f1\b\i\lang1033\fs24 Equinoctialis\plain \f1\i\lang1033\fs24  uel equidialis \plain \f1\b\i\lang1033\fs24 proprie ebennechtig \plain \f1\lang1033\fs24 [Ex quo\plain \f1\lang1033\fs20  \plain \f1\lang1033\fs24 E 215; Brev. Druck S. 182], \plain \f1\i\lang1033\fs24 ...\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  \plain \f1\b\i\lang1033\fs24 Equum\plain \f1\i\lang1033\fs24  n. ... est similitudo, iusticia ... Fur furatur equum, suspenditur et manet equum \plain \f1\lang1033\fs24 [\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia Nr. 10100] \plain \f1\i\lang1033\fs24 ... \plain \f1\lang1033\fs24 [Ex quo\plain \f1\lang1033\fs20  \plain \f1\lang1033\fs24 E 202 und Brev. Druck S. 182: Equus].
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Zum \u8218 \'82Voc. Brev.\lquote , vgl. Hs.: Cod. Guelf. 370 Helmst., 87\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , Druck 1478, Bild 180-182.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

