\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (li. Spalte) [\plain \f1\b\lang1033\fs24 Evangeliste\plain \f1\lang1033\fs24  ...] \plain \f1\i\lang1033\fs24 \u8230 \'85 tercius habet dispositionem leonis, scilicet Marcus, quia sicut leo rugit ... quartus, scilicet Lucas, habet dispositionem bouis seu thauri ... \plain \f1\lang1033\fs24 [Ex quo --],\plain \f1\i\lang1033\fs24  \plain \f1\b\i\lang1033\fs24 Evax \plain \f1\i\lang1033\fs24 est proprium nomen principis de Arabia ... \plain \f1\lang1033\fs24 [Ex quo, E 299; Brev. --], \plain \f1\b\i\lang1033\fs24 Eukaristia \plain \f1\i\lang1033\fs24 dicitur bona gratia ad salute animarum, eciam est sangwis Christi ...\plain \f1\lang1033\fs24  [Ex quo E 300, Brev. Druck S. 186],\plain \f1\i\lang1033\fs24  \plain \f1\b\i\lang1033\fs24 Eucraton \plain \f1\i\lang1033\fs24 grecum indeclinabile dicitur aliquis habens bonam naturam ... ab eu quod est bonum et crasis: natura \plain \f1\lang1033\fs24 [Ex quo, E 300.4; Brev. --], \plain \f1\i\lang1033\fs24 ... - ... \plain \f1\b\i\lang1033\fs24 Eumorphus \plain \f1\i\lang1033\fs24 bene formatus ... \plain \f1\lang1033\fs24 [Ex quo --, Brev. -- ],\plain \f1\i\lang1033\fs24  \plain \f1\b\i\lang1033\fs24 Eunuchus \plain \f1\i\lang1033\fs24 est spado uel castratus ... \plain \f1\lang1033\fs24 [Ex quo E 318, Brev. Druck S. 187].
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Zum \u8218 \'82Voc. Brev.\lquote , vgl. Druck 1478, Bild 186f.}

