\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 2r-103r}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tschechische \u220 \'dcbersetzung der Konstanzer Prozessakten der Magister Johannes Hus und Hieronymus von Prag}}
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\i\lang1024\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 L}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 <}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 \u233 \'e9ta od narozenie p\u225 \'e1n\u283 \'ec MoCCCCoXV}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\super\lang1024\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17  v indici\u237 \'ed osm\u250 \'fa, za biskupstvie najsv\u283 \'ect\u283 \'ecj\u353 \'9aiho v Kristu otce a p\u225 \'e1na na\u353 \'9aeho}}\plain \f2\i\lang1024\fs24 , pana Jana, bo\u382 \'9esk\u253 \'fdm z\u345 \'f8\u237 \'edzen\u237 \'edm pape\u382 \'9ee dvac\u225 \'e1t\u233 \'e9ho t\u345 \'f8et\u237 \'edho l\u233 \'e9ta jeho p\u225 \'e1t\u233 \'e9ho, sedmn\u225 \'e1ct\u233 \'e9ho dne m\u283 \'ecsice dubna sebr\u225 \'e1nie \u353 \'9aest\u233 \'e9 concilium Constanciensk\u233 \'e9ho, v n\u283 \'ecm\u382 \'9e jest ulo\u382 \'9een puohon proti Jeronymovi z Prahy v p\u345 \'f8i viery: >S<watosvat\u253 \'fd zbor, obecn\u233 \'e9 concilium Constansk\u233 \'e9 \u269 \'e8in\u283 \'ec, v duchu svat\u233 \'e9m v\u283 \'ecrn\u283 \'ec sebran\u253 \'fd, obnecn\u250 \'fa cierkev ritie\u345 \'f8uj\u237 \'edc\u237 \'ed vyzn\u225 \'e1vaje, Jeronymovi z Prahy, kter\u233 \'e9z se mistrem ...\~\endash \~... T\u233 \'e9\u382 \'9e tak\u233 \'e9 vyznali js\u250 \'fa vieru prav\u250 \'fa slavn\u233 \'e9 pam\u283 \'ecti Mistra Jana Wygleffa, kter\u253 \'fd\u382 \'9eto Mistr Jan Wygleff byl sepsal tract\u225 \'e1t proti \u345 \'f8\u225 \'e1du duchovniemu i sv\u283 \'ectsk\u233 \'e9mu Krysta odporn\u253 \'fdch. L\u233 \'e9tha od narozenie P\u225 \'e1n\u283 \'ec M\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 CCCC\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 XV\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  za pape\u382 \'9ee pana Jana XXIII\plain \f1\i\super\lang1033\fs24 o\plain \f2\i\lang1024\fs24 , l\u233 \'e9tha jeho p\u225 \'e1t\u233 \'e9ho, sedmn\u225 \'e1ct\u233 \'e9ho dne m\u283 \'ecsiece dubna.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1024\fs20 Nur in dieser Hs. \u252 \'fcberliefert. \endash  Ed.: Historick\u233 \'e9 spisy petra z Mlado\u328 \'f2ovic a jin\u233 \'e9 zpr\u225 \'e1vy a pam\u283 \'ecti o m. Janovi Husovi a m. Jeronymovi z Prahy, hg. v. V\u225 \'e1clav \plain \f1\scaps\lang1033\fs20 Novotn\plain \f1\scaps\lang1033\fs20 \u253 \'fd\plain \f1\lang1033\fs20  (Fontes rerum Bohemicarum VIII), Prag 1932, S. 247-318, Nr. XIII (online unter: https://sources.cms.flu.cas.cz/src/index.php?s=v&cat=11&bookid=182). Zum Text vgl. \plain \f1\scaps\lang1033\fs20 Novotn\plain \f1\scaps\lang1033\fs20 \u253 \'fd\plain \f1\lang1033\fs20 , Einleitung, S. LXXVII-LXXXII.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

