\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 132v-138v}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Poggio Bracciolini}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistola de morte Hieronymi, \u228 \'e4lteste tschechische \u220 \'dcbersetzung}}
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberschrift: \plain \f2\i\lang1024\fs24 Epi\u353 \'9atola p\u345 \'f8ev\u253 \'fdmluvn\u233 \'e9ho mu\u382 \'9ee Poegia Florent\u253 \'fdnskeho, kter\u250 \'fa\u382 \'9e psal k Leonardovi Aret\u253 \'fdnsk\u233 \'e9mu o smrti mistra Jeron\u253 \'fdma \u268 \'c8echa, kter\u233 \'e9ho\u382 \'9e sbor konstansk\u253 \'fd pro pravdu z\u225 \'e1kona bo\u382 \'9eieho up\u225 \'e1lil jest, takto se po\u269 \'e8\u237 \'edn\u225 \'e1\plain \f1\lang1033\fs24 . Text: \plain \f2\i\lang1024\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 P}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 <}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 ogius mnoh\u233 \'e9 pozdravenie vzkazuje sv\u233 \'e9mu Leonardovi Aret\u253 \'fdnsk\u233 \'e9mu}}\plain \f2\i\lang1024\fs24  ...\~\endash \~... Ale necht\u283 \'ecl sem b\u253 \'fdti p\u345 \'f8ieli\u353 \'9a mluvn\u253 \'fd. M\u283 \'ecj\u382 \'9e se dob\u345 \'f8e, ut\u283 \'ec\u353 \'9aen\u253 \'fd Leonarde! V Constanc\u237 \'ed t\u345 \'f8et\u237 \'ed den M\u225 \'e1je m\u283 \'ecs\u237 \'edce, kdy\u382 \'9eto Jeronimus muky trp\u283 \'ecl, l\u233 \'e9ta bo\u382 \'9e\u237 \'edho M\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 CCCC\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 XVII\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Diese \u220 \'dcbersetzung nur hier \u252 \'fcberliefert. Ed. (in Paralleldruck mit der lat. Version): \plain \f1\scaps\lang1033\fs20 Novotn\plain \f1\scaps\lang1033\fs20 \u253 \'fd\plain \f1\lang1033\fs20 , FRB VIII (wie 2r), S. 323-334, Nr. XV, zu \u228 \'e4lteren Abdrucken ebd., S. XC.\endash  Zum Text der tschechischen \u220 \'dcbersetzung vgl. \plain \f1\scaps\lang1033\fs20 Novotn\plain \f1\scaps\lang1033\fs20 \u253 \'fd\plain \f1\lang1033\fs20 , S. LXXVIII-XC. Zur Verbreitung des Briefs in lat. und dt. Sprache vgl\plain \f1\scaps\lang1033\fs20 . Krzenck\plain \f1\lang1033\fs20 , S. 13, Anm. 14. Hinweise und Links zu Handschriften, alten Drucken, \u220 \'dcbersetzungen und Ausgaben der Epistola de morte Hieronymi unter www.geschichtsquellen.de/werk/5006.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

