\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 a. ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 139r-143r}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Tschechische \u220 \'dcbersetzung des Protestschreibens des b\u246 \'f6hmischen und m\u228 \'e4hrischen Adels vom 2. September 1415}}\plain \f1\lang1033\fs24 . \u220 \'dcberschrift (rot unterstrichen): \plain \f2\i\lang1024\fs24 List p\u225 \'e1nuov \u269 \'e8esk\u253 \'fdch a moravsk\u253 \'fdch do Konstancie\plain \f1\lang1033\fs24 . Text: >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 N}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 <}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 ajpoctiv\u283 \'ecj\u353 \'9a\u237 \'edm v Kristu otcuom a p\u225 \'e1nuom, kardin\u225 \'e1luom, patriarch\u225 \'e1m, arcibiskupuom, biskupuom, leg\u225 \'e1tuom, doktoruom, mistruom i v\u353 \'9aemu sboru konstansk\u233 \'e9mu}}\plain \f2\i\lang1024\fs24 . My, \u268 \'c8en\u283 \'eck z Vesel\u233 \'e9 a z Vartemburka, najvy\u353 \'9a\u353 \'9a\u237 \'ed purkrabie pra\u382 \'9esk\u253 \'fd ...\~\endash \~... v\u353 \'9aelik\u250 \'fa b\u225 \'e1zen i n\u225 \'e1lezky lidsk\u233 \'e9 na odpor u\u269 \'e8in\u283 \'ecn\u233 \'e9. D\u225 \'e1n v Praze ...
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Ed.: Franti\u353 \'9aek \plain \f1\scaps\lang1033\fs20 Palack\plain \f1\scaps\lang1033\fs20 \u253 \'fd\plain \f2\lang1024\fs20 , Akta We\u345 \'f8ejn\u225 \'e1 i Sn\u283 \'ecmown\u237 \'ed w \u268 \'c8ech\u225 \'e1ch i w Moraw\u283 \'ec od r. 1414 do 1428, in: Archiv \u269 \'e8esk\u253 \'fd 3 (1844) (online: https://sources.cms.flu.cas.cz/src/index.php?s=v&action=jdi&cat=10&bookid=794), S. 187-193, Nr. 6. Neuedition und Literatur: Petr \plain \f2\scaps\lang1024\fs20 \u268 \'c8\plain \f2\scaps\lang1024\fs20 ornej\plain \f2\lang1024\fs20  u. a., St\u237 \'ed\u382 \'9en\u253 \'fd list \u269 \'e8esk\u233 \'e9 a moravsk\u233 \'e9 \u353 \'9alechty proti up\u225 \'e1len\u237 \'ed mistra Jana Husa 1415-2015, Okrouhlice 2015. Vgl. au\u223 \'dferdem: Protestbrief des b\u246 \'f6hmischen und m\u228 \'e4hrischen Adels, in: Herder-Institut (Hg.): Dokumente und Materialien zur ostmitteleurop\u228 \'e4ischen Gesc\plain \f1\lang1033\fs20 hichte. Themenmodul "Hus und die Hussiten", bearb. v. Thomas \plain \f1\scaps\lang1033\fs20 Krzenck\plain \f1\lang1033\fs20 . URL: https://www.herder-institut.de//digitale-angebote/dokumente-und-materialien/themenmodule/quelle/3153/details.html (Zugriff am 7.9.2023), mit Ausf\u252 \'fchrungen zum Kontext, Ausgabe des tschechischen und lateinischen Texts und einer deutschen \u220 \'dcbersetzung sowie weiterer Literatur. \endash  Zum Kontext vgl. besonders Franti\u353 \'9aek \plain \f1\scaps\lang1033\fs20 \u352 \'8a\plain \f1\scaps\lang1033\fs20 mahel\plain \f1\lang1033\fs20 , Die Hussitische Revolution, Bd. II (MGH, Schriften, Bd. 43,2), S. 930-950 (zum Hintergrund und zur Lage in Prag); zum Protestschreiben selbst wiederum Robert \plain \f1\scaps\lang1033\fs20 Novotn\plain \f1\scaps\lang1033\fs20 \u253 \'fd\plain \f2\lang1024\fs20 , Organizace protestn\u237 \'ed akce proti Husovu up\u225 \'e1len\u237 \'ed (Die Organisation der Protestaktion gegen Hussens Verbrennung), in: Jan Hus 1415 a 600 let pot\u233 \'e9. VII. Mezin\u225 \'e1rodn\u237 \'ed husitologick\u233 \'e9 sympozium T\u225 \'e1bor 23.-25. \u269 \'e8ervna 2015, hg. v. Jakub \plain \f2\scaps\lang1024\fs20 Smr\plain \f2\scaps\lang1024\fs20 \u269 \'e8\plain \f2\scaps\lang1024\fs20 ka\plain \f2\lang1024\fs20  / Zden\u283 \'eck \plain \f1\scaps\lang1033\fs20 Vyb\plain \f1\scaps\lang1033\fs20 \u237 \'ed\plain \f1\scaps\lang1033\fs20 ral\plain \f1\lang1033\fs20  (Husitsk\u253 \'fd T\u225 \'e1bor, Supplementum 4), T\u225 \'e1bor 2016, S. 153-164.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 b. ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 143r-145v}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Schreiben}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 K\u246 \'f6nig Sigismunds}}\plain \f1\lang1033\fs24  von Luxemburg an die b\u246 \'f6hmischen Adeligen, in dem er auf die Beschwerdeartikel des b\u246 \'f6hmischen Landtags antwortet, ohne Datum [1421]. \u220 \'dcberschrift: \plain \f2\i\lang1024\fs24 List poslan\u253 \'fd od kr\u225 \'e1le Zigmunda p\u225 \'e1nuom \u269 \'e8esk\u253 \'fdm\plain \f1\lang1033\fs24 . Text: >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 M<y Zigmund, z bo\u382 \'9e\u237 \'ed milosti \u345 \'f8\u237 \'edmsk\u253 \'fd kr\u225 \'e1l, po v\u353 \'9ae \u269 \'e8asy rozmno\u382 \'9eitel \u345 \'f8\u237 \'ed\u353 \'9ae, a uhersk\u253 \'fd}}\plain \f2\i\lang1024\fs24 , \u269 \'e8esk\u253 \'fd, dalmacsk\u253 \'fd, charv\u225 \'e1tsk\u253 \'fd, sedmihradsk\u253 \'fd, bosensk\u253 \'fd, moravsk\u253 \'fd, slezitsk\u253 \'fd, lu\u382 \'9enitsk\u253 \'fd, brambursk\u253 \'fd a lucembursk\u253 \'fd kr\u225 \'e1l, v\u225 \'e1m v\u353 \'9aem p\u225 \'e1nuom, rytie\u345 \'f8uom, pano\u353 \'9aem ...\~\endash \~... nebudeme tomu moci co u\u269 \'e8initi, ne\u382 \'9e na to p\u345 \'f8ijde, \u382 \'9ee ta zem\u283 \'ec mus\u237 \'ed do konce zahyn\u250 \'fati. Datum\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Ed.: \plain \f1\scaps\lang1033\fs20 Palack\plain \f1\scaps\lang1033\fs20 \u253 \'fd\plain \f2\lang1024\fs20 , in: Archiv \u269 \'e8esk\u253 \'fd 3 (wie 139r), S. 232-233. \endash  Der Text stammt aus der Chronik des Laurentius von B\u345 \'f8ezov\u225 \'e1. Zum Kontext aus diplomatischer Sicht vgl. Ivan \plain \f2\scaps\lang1024\fs20 Hlav\plain \f2\scaps\lang1024\fs20 \u225 \'e1\u269 \'e8\plain \f2\scaps\lang1024\fs20 ek\plain \f2\lang1024\fs20 , Das diplomatische Material in der hussitischen Chronik des Laurentius von B\u345 \'f8ezov\u225 \'e1, in: Folia diplomatica II, Brno 1976, S. 173-186 (hier S. 183f. zu den antihussitischen Urkunden). Deutsche \u220 \'dcbersetzung: Die Hussiten. Die Chronik des Laurentius von B\u345 \'f8ezov\u225 \'e1 1414-1421. Aus dem Lateinischen und Alttschechischen \u252 \'fcbersetzt, eingeleitet und \plain \f1\lang1033\fs20 erkl\u228 \'e4rt von Josef \plain \f1\scaps\lang1033\fs20 Bujnoch\plain \f1\lang1033\fs20 , Graz / Wien / K\u246 \'f6ln 1988, S. 239-242.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 c. ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 145v-148r}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Schreiben}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 K\u246 \'f6nig Sigismunds}}\plain \f1\lang1033\fs24  an die b\u246 \'f6hmischen Adligen, Paris, 21. M\u228 \'e4rz 1416. \plain \f2\i\lang1024\fs24 >Litera domini Sigismundi regis Vngarie etc. reprehensiua baronum et aliorum fautorum Wiklephistarum.< >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 M}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 <}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 y Zigmund, z bo\u382 \'9e\u237 \'ed milosti \u345 \'f8\u237 \'edmsk\u253 \'fd kr\u225 \'e1l, po v\u353 \'9ae \u269 \'e8asy rozmno\u382 \'9eitel \u345 \'f8\u237 \'ed\u353 \'9ae a uhersk\u253 \'fd kr\u225 \'e1l etc. vzkazujem urozen\u253 \'fdm Lackovi}}\plain \f2\i\lang1024\fs24  z Krava\u345 \'f8, hajtmanovi moravsk\u233 \'e9mu, Bo\u269 \'e8kovi z Kun\u353 \'9at\u225 \'e1ta, odjinud z Pod\u283 \'ecbrad, \u268 \'c8enkovi z Vartemberka a v\u353 \'9aem jin\u253 \'fdm p\u225 \'e1nuom, rytie\u345 \'f8uom a pano\u353 \'9aem v \u268 \'c8ech\u225 \'e1ch a v Morav\u283 \'ec ...\~\endash \~... ne\u382 \'9e, \u382 \'9ee je to na\u353 \'9aeho mil\u233 \'e9ho bratra hodn\u233 \'e9 a po\u269 \'e8estn\u233 \'e9 Va\u353 \'9ae \u269 \'e8estn\u233 \'e9 a zemsk\u233 \'e9 dobr\u233 \'e9. Datum Parisius\u8230 \'85
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Ed.: Documenta Mag. Joannis Hus ..., hg. v. Franti\u353 \'9aek \plain \f1\scaps\lang1033\fs20 Palack\plain \f1\scaps\lang1033\fs20 \u253 \'fd\plain \f1\lang1033\fs20 , Prag 1869, S. 609-611 (S. 611-613 die lateinische Fassung).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

