\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 d. ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 148v-150r}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Schreiben}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 K\u246 \'f6nig Sigismunds}}\plain \f1\lang1033\fs24  an die in Basel weilenden B\u246 \'f6hmen (1433). \plain \f2\i\lang1024\fs24 >List v\u283 \'ec\u345 \'f8\u237 \'edc\u237 \'ed od kr\u225 \'e1le Zigmunda poslan\u253 \'fd k \u268 \'c8echuom do Basil\u233 \'e9 po panu Mikul\u225 \'e1\u353 \'9aovi Rytie\u345 \'f8i z Vlad\u283 \'ecn\u237 \'edna s jin\u253 \'fdm poselstv\u237 \'edm< >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 M<y Zigmund, z bo\u382 \'9e\u237 \'ed milosti \u345 \'f8\u237 \'edmsk\u253 \'fd kr\u225 \'e1l}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 \u8230 \'85}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17  vzkazujem urozen\u253 \'fdm, slovutn\u253 \'fdm a poctiv\u253 \'fdm duchovn\u237 \'edm i sv\u283 \'ectsk\u253 \'fdm}}\plain \f2\i\lang1024\fs24  posluom kr\u225 \'e1lovstvie \u269 \'e8esk\u233 \'e9ho a markrabstvie moravsk\u233 \'e9ho k svatosvat\u233 \'e9mu Concilium v Basil\u237 \'ed poslan\u253 \'fdm milost na\u353 \'9ai a \u382 \'9e\u225 \'e1dost cel\u233 \'e9 jednoty i v\u353 \'9aeho dobr\u233 \'e9ho ...\~\endash \~... aby\u353 \'9ate jemu toho \u250 \'fapln\u283 \'ec sv\u283 \'ec\u345 \'f8ili, jako\u382 \'9e by chme o to\plain \f1\i\lang1033\fs24  sami s v\u225 \'e1mi rozmluvili. D\u225 \'e1n\u8230 \'85
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Nur in dieser Hs. \u252 \'fcberliefert. Ed.: \plain \f1\scaps\lang1033\fs20 Goll\plain \f1\lang1033\fs20  1877 (s.\~o. Lit.), S. 385-387 (Beilage A, Teil 1).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

