\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 165r-169v}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Hussitische Schm\u228 \'e4hschrift}}\plain \f1\b\lang1033\fs24  gegen K\u246 \'f6nig Sigismund von Luxemburg
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  \plain \f2\i\lang1024\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 Z}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\lang1024\fs24\chcbpat17 <}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 igmund, uhersk\u253 \'fd kr\u225 \'e1l, \u250 \'fahlavn\u237 \'ed \u269 \'e8esk\u233 \'e9ho jazyka nep\u345 \'f8\u237 \'edtel, mnoho zl\u233 \'e9ho proti korun\u283 \'ec \u269 \'e8esk\u233 \'e9 \u269 \'e8inil}}\plain \f2\i\lang1024\fs24  ...\~\endash \~... aby za dl\u250 \'fah\u233 \'e9 \u269 \'e8asy v zapomenut\u237 \'ed nebylo d\u225 \'e1no, kr\u225 \'e1tce v tomto seps\u225 \'e1n\u237 \'ed ozn\u225 \'e1meno bu\u271 \'ef etc.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Ed.: \plain \f1\scaps\lang1033\fs20 Goll\plain \f1\lang1033\fs20  1877 (s.\~o. Lit.), S. 389\endash 392, Beilage B.\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs20 Schm\u228 \'e4hschrift mit Blick auf die Hussitenkriege, insonderheit die Schlacht bei Tachau (Tachov) 1427 und Taus (Doma\u382 \'9elice) 1431 sowie einer Erw\u228 \'e4hnung der Kompaktaten.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

